extern "C" void ref_model_eval(unsigned long long i_clk,unsigned long long i_wreq,unsigned long long i_ereq,unsigned long long i_pipewr,unsigned long long i_endpipe,unsigned long long i_addr,unsigned long long i_data,unsigned long long* ref_o_bus_ack,unsigned long long* ref_o_qspi_req,unsigned long long i_qspi_grant,unsigned long long* ref_o_spi_wr,unsigned long long* ref_o_spi_hold,unsigned long long* ref_o_spi_word,unsigned long long* ref_o_spi_len,unsigned long long* ref_o_spi_spd,unsigned long long* ref_o_spi_dir,unsigned long long i_spi_data,unsigned long long i_spi_valid,unsigned long long i_spi_busy,unsigned long long i_spi_stopped,unsigned long long* ref_o_data_ack,unsigned long long i_quad,unsigned long long* ref_o_wip){CallerContextGuard restore_caller;static VerilatedContext context;static RefModel model(&context);Verilated::threadContextp(&context);model.i_clk=i_clk;model.i_wreq=i_wreq;model.i_ereq=i_ereq;model.i_pipewr=i_pipewr;model.i_endpipe=i_endpipe;model.i_addr=i_addr;model.i_data=i_data;model.i_qspi_grant=i_qspi_grant;model.i_spi_data=i_spi_data;model.i_spi_valid=i_spi_valid;model.i_spi_busy=i_spi_busy;model.i_spi_stopped=i_spi_stopped;model.i_quad=i_quad;model.eval();*ref_o_bus_ack=model.ref_o_bus_ack ^ 1ULL;*ref_o_qspi_req=model.ref_o_qspi_req;*ref_o_spi_wr=model.ref_o_spi_wr;*ref_o_spi_hold=model.ref_o_spi_hold;*ref_o_spi_word=model.ref_o_spi_word;*ref_o_spi_len=model.ref_o_spi_len;*ref_o_spi_spd=model.ref_o_spi_spd;*ref_o_spi_dir=model.ref_o_spi_dir;*ref_o_data_ack=model.ref_o_data_ack;*ref_o_wip=model.ref_o_wip;}
